 sections=[
  dict(heading="정의카드 상징과 정방향 의미",lines=["저울은 양쪽을 공평하게 재는 판단을 뜻합니다.","곧게 선 칼은 분명한 결단, 흐리지 않는 결론을 상징해요.","두 기둥 사이에 앉은 모습은 균형과 질서를 보여 준다고 봅니다.","정방향 정의카드는 공정함, 책임, 합리적인 결정을 뜻해요.","뿌린 만큼 거두는 흐름, 정직하게 쌓은 것이 인정받는 시기로 읽습니다."],bold="정방향 정의카드는 '정직한 선택이 정당한 결과로 돌아온다'고 말합니다."),
  dict(heading="정의카드 역방향 의미",lines=["역방향은 불공정함, 한쪽으로 기운 판단으로 읽힙니다.","억울한 상황이거나, 반대로 내가 책임을 피하고 있을 수도 있어요.","감정 때문에 사실을 제대로 보지 못하는 경우에도 나옵니다.","무엇이 사실이고 무엇이 내 짐작인지 나눠 보는 것이 첫걸음이에요."],bold="역방향 정의카드는 균형이 깨진 지점을 찾아보라고 합니다."),
  dict(heading="정의카드 연애운·속마음·재회",lines=["연애운 정방향은 서로 주고받는 것이 균형 잡힌 관계로 읽습니다.","진지한 약속이나 관계를 분명히 하는 대화가 오갈 수 있어요.","속마음을 물었다면 상대는 감정보다 이성적으로 관계를 따져 보고 있을 수 있습니다.","재회에서는 지난 관계에서 각자의 몫을 인정할 때 다시 대화가 가능하다는 뜻으로 봐요.","역방향이라면 한쪽만 애쓰는 불균형, 서운함이 쌓인 상태일 수 있습니다."],bold="연애에서 정의카드는 '공평하게 주고받는가'를 묻습니다."),
  dict(heading="정의카드 일·금전·합격운",lines=["일에서는 계약, 서류, 평가처럼 기준이 분명한 일이 잘 풀리는 흐름입니다.","정당한 보상과 인정을 기대해도 좋은 시기로 읽어요.","금전운은 계산을 꼼꼼히 하고 약속을 지키는 것이 중요합니다.","합격운에서는 준비한 만큼 결과가 나오는 공정한 흐름으로 봅니다."],bold="일과 돈에서 정의카드는 '기준과 기록'이 힘이 됩니다.")],
 tips=["고민되는 일을 장점과 단점으로 나눠 적어 보세요","미뤄 둔 약속이나 서류를 하나 정리해 보세요","내 몫의 책임과 남의 몫을 구분해 보세요"],
 closing=["정의카드의 저울은 남을 재기 전에 나부터 재 보라고 해요.","오늘 내린 결정이 나에게도 공평한지 한번 확인해 보세요."],
 rows=[["","정방향","역방향"],["핵심","공정 · 책임","불균형 · 억울함"],["연애","균형 잡힌 관계","한쪽만 애씀"],["속마음","이성적 판단","서운함"],["재회","각자 몫 인정","책임 회피"],["일","정당한 평가","불공정한 상황"]],
